/**
 * Resolve a fun fact for the given locale, falling back to the English base
 * text (ARTWORK_FACTS) when a translation is missing. Returns undefined if the
 * artwork has no fact at all (so the card stays hidden).
 */
export function factFor(id: string, locale: Locale): string | undefined {
  return FACTS_L[id]?.[locale] ?? ARTWORK_FACTS[id];
}
